// Battle engine: Gen-3 mechanics (type-based phys/spec split, stat stages,
// status, catching, exp). Runs as an async script; draws its own scene.
window.Battle = (() => {
  const W = 240;

  const wait = (ms) => new Promise(r => setTimeout(r, ms));
  const rnd = (n) => (Math.random() * n) | 0;
  const chance = (pct) => Math.random() * 100 < pct;

  const STAGE_MULT = (s) => s >= 0 ? (2 + s) / 2 : 2 / (2 - s);
  const ACC_MULT = (s) => s >= 0 ? (3 + s) / 3 : 3 / (3 - s);

  const FIXED = { 'dragon-rage': () => 40, 'sonic-boom': () => 20 };
  const LEVEL_DMG = new Set(['seismic-toss', 'night-shade', 'psywave']);
  const OHKO = new Set(['fissure', 'guillotine', 'horn-drill']);
  const SUICIDE = new Set(['self-destruct', 'explosion']);
  const UNSUPPORTED = new Set(['bide', 'disable', 'substitute', 'mimic', 'mirror-move', 'rage', 'teleport', 'splash', 'roar', 'whirlwind']);

  function makeSide(mon) {
    return {
      mon, stages: { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0 },
      confusion: 0, reflect: 0, lightScreen: 0, focused: false, seeded: false,
      lastPhysDmg: 0, transformed: null, flinched: false,
    };
  }

  function effStat(side, key) {
    let v = side.transformed ? side.transformed.stats[key] : side.mon.stats[key];
    v = Math.floor(v * STAGE_MULT(side.stages[key]));
    if (key === 'atk' && side.mon.status === 'brn') v = Math.floor(v / 2);
    if (key === 'spe' && side.mon.status === 'par') v = Math.floor(v / 4);
    return Math.max(1, v);
  }
  const types = (side) => side.transformed ? side.transformed.types : Pkmn.species(side.mon).types;
  const moveList = (side) => side.transformed ? side.transformed.moves : side.mon.moves;

  // ---- The battle scene ----------------------------------------------------
  let scene = null;

  function draw(ctx) {
    if (!scene) return;
    const s = scene;
    // backdrop
    const g = ctx.createLinearGradient(0, 0, 0, 112);
    g.addColorStop(0, '#a8e0f8'); g.addColorStop(1, '#c8f0d0');
    ctx.fillStyle = g; ctx.fillRect(0, 0, W, 112);
    ctx.fillStyle = '#90c890';
    ctx.beginPath(); ctx.ellipse(172, 76, 52, 14, 0, 0, 7); ctx.fill();
    ctx.beginPath(); ctx.ellipse(52, 110, 56, 16, 0, 0, 7); ctx.fill();

    // enemy
    if (s.foe.visible) {
      const img = Gfx.monSprite(s.foe.mon.id, 'front');
      ctx.save();
      if (s.foe.flash % 2 === 1) ctx.globalAlpha = 0.25;
      const sc = s.foe.scale ?? 1;
      if (img.complete) ctx.drawImage(img, 140 + s.foe.ox + 32 * (1 - sc), 14 + s.foe.oy + 64 * (1 - sc), 64 * sc, 64 * sc);
      ctx.restore();
    }
    if (s.ballAnim) {
      ctx.fillStyle = '#e84848'; ctx.beginPath(); ctx.arc(s.ballAnim.x, s.ballAnim.y, 5, Math.PI, 0); ctx.fill();
      ctx.fillStyle = '#f8f8f8'; ctx.beginPath(); ctx.arc(s.ballAnim.x, s.ballAnim.y, 5, 0, Math.PI); ctx.fill();
      ctx.fillStyle = '#303030'; ctx.fillRect(s.ballAnim.x - 5, s.ballAnim.y - 1, 10, 2);
    }
    // player
    if (s.me.visible) {
      const img = Gfx.monSprite(s.me.mon.id, 'back');
      ctx.save();
      if (s.me.flash % 2 === 1) ctx.globalAlpha = 0.25;
      if (img.complete) ctx.drawImage(img, 16 + s.me.ox, 52 + s.me.oy, 64, 64);
      ctx.restore();
    }

    // enemy info box
    drawInfo(ctx, 4, 8, s.foe, false);
    // player info box
    drawInfo(ctx, 132, 76, s.me, true);

    UI.drawTextboxFrame(ctx);
  }

  function drawInfo(ctx, x, y, side, mine) {
    const mon = side.mon;
    Gfx.frame(ctx, x, y, 104, mine ? 34 : 28);
    Gfx.text(ctx, Pkmn.dname(mon).slice(0, 10), x + 5, y + 4);
    Gfx.text(ctx, 'LV' + mon.level, x + 74, y + 4, '#586068');
    Gfx.hpBar(ctx, x + 24, y + 14, 70, side.shownHp ?? mon.hp, mon.stats.hp);
    Gfx.text(ctx, 'HP', x + 6, y + 12, '#e88030');
    if (mon.status) Gfx.text(ctx, mon.status.toUpperCase(), x + 5, y + 19, '#c05048');
    if (mine) {
      Gfx.text(ctx, Math.max(0, Math.round(side.shownHp ?? mon.hp)) + '/' + mon.stats.hp, x + 40, y + 20, '#586068');
      const sp = Pkmn.species(mon);
      const cur = Pkmn.expForLevel(sp.growth, mon.level);
      const next = Pkmn.expForLevel(sp.growth, mon.level + 1);
      const frac = mon.level >= 100 ? 0 : Math.min(1, (mon.exp - cur) / Math.max(1, next - cur));
      ctx.fillStyle = '#404048'; ctx.fillRect(x + 24, y + 29, 70, 3);
      ctx.fillStyle = '#48a8e8'; ctx.fillRect(x + 24, y + 29, Math.floor(70 * frac), 3);
      Gfx.text(ctx, 'EXP', x + 4, y + 27, '#48a8e8');
    }
  }

  async function animHp(side, to) {
    const from = side.shownHp ?? side.mon.hp;
    const steps = 18;
    for (let i = 1; i <= steps; i++) {
      side.shownHp = from + (to - from) * (i / steps);
      await wait(22);
    }
    side.shownHp = to;
  }

  async function hitAnim(target, eff) {
    if (eff > 1) Audio2.superHit(); else if (eff < 1) Audio2.weakHit(); else Audio2.hit();
    for (let i = 0; i < 6; i++) { target.flash++; await wait(50); }
    target.flash = 0;
  }
  async function lungeAnim(side, mine) {
    const d = mine ? 8 : -8;
    side.ox = d; await wait(70); side.ox = 0; await wait(50);
  }

  // ---- Mechanics -----------------------------------------------------------
  function calcDamage(atkSide, defSide, mv, crit) {
    const level = atkSide.mon.level;
    const physical = isPhysicalType(mv.type);
    let A = effStat(atkSide, physical ? 'atk' : 'spa');
    let D = effStat(defSide, physical ? 'def' : 'spd');
    if (crit) { // crits ignore attacker's negative / defender's positive stages
      A = Math.max(A, (atkSide.transformed ?? atkSide.mon).stats[physical ? 'atk' : 'spa']);
      D = Math.min(D, (defSide.transformed ?? defSide.mon).stats[physical ? 'def' : 'spd']);
    }
    let dmg = Math.floor(Math.floor(Math.floor(2 * level / 5 + 2) * mv.power * A / D) / 50) + 2;
    if (!crit) {
      if (physical && defSide.reflect > 0) dmg = Math.floor(dmg / 2);
      if (!physical && defSide.lightScreen > 0) dmg = Math.floor(dmg / 2);
    }
    if (crit) dmg *= 2;
    const stab = types(atkSide).includes(mv.type) ? 1.5 : 1;
    const eff = typeEffect(mv.type, types(defSide));
    dmg = Math.floor(dmg * stab * eff);
    dmg = Math.floor(dmg * (85 + rnd(16)) / 100);
    return { dmg: Math.max(1, dmg), eff };
  }

  async function applyDamage(side, amount) {
    side.mon.hp = Math.max(0, side.mon.hp - amount);
    await animHp(side, side.mon.hp);
  }

  const statName = { attack: 'ATTACK', defense: 'DEFENSE', 'special-attack': 'SP. ATK', 'special-defense': 'SP. DEF', speed: 'SPEED', accuracy: 'ACCURACY', evasion: 'EVASIVENESS' };
  const statKey = { attack: 'atk', defense: 'def', 'special-attack': 'spa', 'special-defense': 'spd', speed: 'spe', accuracy: 'acc', evasion: 'eva' };

  async function applyStatChanges(targetSide, changes, name) {
    for (const sc of changes) {
      const k = statKey[sc.stat];
      if (!k) continue;
      const before = targetSide.stages[k];
      targetSide.stages[k] = Math.max(-6, Math.min(6, before + sc.change));
      const moved = targetSide.stages[k] - before;
      if (moved === 0) {
        await UI.message(`${name}'s ${statName[sc.stat]} won't go ${sc.change > 0 ? 'higher' : 'lower'}!`);
      } else {
        await UI.message(`${name}'s ${statName[sc.stat]} ${moved > 1 ? 'rose sharply!' : moved === 1 ? 'rose!' : moved < -1 ? 'fell harshly!' : 'fell!'}`);
      }
    }
  }

  const AIL_NAME = { paralysis: 'par', poison: 'psn', burn: 'brn', sleep: 'slp', freeze: 'frz' };
  async function applyAilment(targetSide, ail) {
    const mon = targetSide.mon, name = Pkmn.dname(mon);
    if (ail === 'confusion') {
      if (targetSide.confusion <= 0) { targetSide.confusion = 2 + rnd(4); await UI.message(`${name} became confused!`); }
      return;
    }
    if (ail === 'leech-seed') {
      if (!targetSide.seeded && !types(targetSide).includes('grass')) {
        targetSide.seeded = true; await UI.message(`${name} was seeded!`);
      }
      return;
    }
    const code = AIL_NAME[ail];
    if (!code || mon.status) return;
    if (code === 'psn' && (types(targetSide).includes('poison') || types(targetSide).includes('steel'))) return;
    if (code === 'brn' && types(targetSide).includes('fire')) return;
    if (code === 'par' && types(targetSide).includes('electric')) return;
    if (code === 'frz' && types(targetSide).includes('ice')) return;
    mon.status = code;
    if (code === 'slp') mon.sleepTurns = 1 + rnd(4);
    const verb = { psn: 'was poisoned!', brn: 'was burned!', par: 'is paralyzed! It may be unable to move!', slp: 'fell asleep!', frz: 'was frozen solid!' };
    await UI.message(`${name} ${verb[code]}`);
  }

  // Execute one move. Returns true if the defender fainted.
  async function execMove(atkSide, defSide, moveSlot, isStruggle = false) {
    const atk = atkSide.mon, def = defSide.mon;
    const aname = Pkmn.dname(atk), dname = Pkmn.dname(def);

    // Pre-move status checks
    if (atk.status === 'slp') {
      if (--atk.sleepTurns <= 0) { atk.status = null; await UI.message(`${aname} woke up!`); }
      else { await UI.message(`${aname} is fast asleep.`); return false; }
    }
    if (atk.status === 'frz') {
      if (chance(20)) { atk.status = null; await UI.message(`${aname} thawed out!`); }
      else { await UI.message(`${aname} is frozen solid!`); return false; }
    }
    if (atkSide.flinched) { atkSide.flinched = false; await UI.message(`${aname} flinched!`); return false; }
    if (atk.status === 'par' && chance(25)) { await UI.message(`${aname} is fully paralyzed!`); return false; }
    if (atkSide.confusion > 0) {
      atkSide.confusion--;
      if (atkSide.confusion === 0) await UI.message(`${aname} snapped out of confusion!`);
      else {
        await UI.message(`${aname} is confused!`);
        if (chance(50)) {
          await UI.message('It hurt itself in its confusion!');
          const A = effStat(atkSide, 'atk'), D = effStat(atkSide, 'def');
          const dmg = Math.max(1, Math.floor(Math.floor(Math.floor(2 * atk.level / 5 + 2) * 40 * A / D) / 50) + 2);
          await hitAnim(atkSide, 1);
          await applyDamage(atkSide, dmg);
          return atk.hp <= 0 ? 'self' : false;
        }
      }
    }

    let mv = isStruggle
      ? { name: 'struggle', displayName: 'STRUGGLE', type: 'normal', power: 50, accuracy: 100, damageClass: 'physical', statChanges: [], priority: 0 }
      : MOVES[moveSlot.name];
    if (!isStruggle) moveSlot.pp = Math.max(0, moveSlot.pp - 1);

    await UI.message(`${aname} used ${mv.displayName.toUpperCase()}!`);

    // Metronome
    if (mv.name === 'metronome') {
      const all = Object.values(MOVES).filter(m => m.power && m.name !== 'metronome');
      mv = all[rnd(all.length)];
      await UI.message(`Waggling a finger let it\nuse ${mv.displayName.toUpperCase()}!`);
    }
    if (UNSUPPORTED.has(mv.name)) { await UI.message('But it failed!'); return false; }

    // Transform
    if (mv.name === 'transform') {
      const src = defSide.transformed ?? { stats: def.stats, types: Pkmn.species(def).types, moves: def.moves };
      atkSide.transformed = {
        id: def.id,
        stats: { ...src.stats, hp: atk.stats.hp },
        types: [...src.types],
        moves: src.moves.map(m => ({ name: m.name, pp: 5, maxPp: 5 })),
      };
      await UI.message(`${aname} transformed into\n${dname}!`);
      return false;
    }

    // Non-damaging utility moves
    if (mv.name === 'rest') {
      if (atk.hp >= atk.stats.hp) { await UI.message('But it failed!'); return false; }
      atk.status = 'slp'; atk.sleepTurns = 2; atk.hp = atk.stats.hp;
      await animHp(atkSide, atk.hp); Audio2.heal();
      await UI.message(`${aname} slept and became\nhealthy!`);
      return false;
    }
    if (mv.name === 'reflect') { atkSide.reflect = 5; await UI.message(`${aname} is protected against\nphysical moves!`); return false; }
    if (mv.name === 'light-screen') { atkSide.lightScreen = 5; await UI.message(`${aname} is protected against\nspecial moves!`); return false; }
    if (mv.name === 'haze') {
      for (const s of [atkSide, defSide]) for (const k in s.stages) s.stages[k] = 0;
      await UI.message('All stat changes were\neliminated!');
      return false;
    }
    if (mv.name === 'focus-energy') { atkSide.focused = true; await UI.message(`${aname} is getting pumped!`); return false; }

    // Accuracy check
    if (mv.accuracy !== null && !OHKO.has(mv.name)) {
      const acc = mv.accuracy * ACC_MULT(atkSide.stages.acc) * (1 / ACC_MULT(defSide.stages.eva));
      if (!chance(acc)) { await UI.message(`${aname}'s attack missed!`); return false; }
    }
    if (OHKO.has(mv.name)) {
      if (def.level > atk.level || !chance(30 + atk.level - def.level)) {
        await UI.message(`${aname}'s attack missed!`); return false;
      }
      await lungeAnim(atkSide, atkSide === scene.me);
      await hitAnim(defSide, 1);
      await applyDamage(defSide, def.hp);
      await UI.message("It's a one-hit KO!");
      return def.hp <= 0;
    }

    // Status-class moves: ailments / stat changes only
    if (mv.damageClass === 'status') {
      if (mv.name === 'dream-eater') { await UI.message('But it failed!'); return false; }
      if (mv.healing > 0) {
        if (atk.hp >= atk.stats.hp) { await UI.message('But it failed!'); return false; }
        atk.hp = Math.min(atk.stats.hp, atk.hp + Math.floor(atk.stats.hp * mv.healing / 100));
        Audio2.heal(); await animHp(atkSide, atk.hp);
        await UI.message(`${aname} regained health!`);
        return false;
      }
      let did = false;
      if (mv.ailment) {
        const before = def.status + '|' + defSide.confusion + '|' + defSide.seeded;
        await applyAilment(defSide, mv.ailment === 'poison' && mv.name === 'toxic' ? 'poison' : mv.ailment);
        did = before !== (def.status + '|' + defSide.confusion + '|' + defSide.seeded);
        if (!did) await UI.message('But it failed!');
        return false;
      }
      if (mv.statChanges.length) {
        const self = mv.target === 'user';
        await applyStatChanges(self ? atkSide : defSide, mv.statChanges, self ? aname : dname);
        return false;
      }
      await UI.message('But it failed!');
      return false;
    }

    // Damaging move
    if (!mv.power && !FIXED[mv.name] && !LEVEL_DMG.has(mv.name)) { await UI.message('But it failed!'); return false; }
    if (mv.name === 'dream-eater' && def.status !== 'slp') { await UI.message('But it failed!'); return false; }

    const eff = typeEffect(mv.type, types(defSide));
    if (eff === 0) { await UI.message(`It doesn't affect ${dname}…`); return false; }

    let hits = 1;
    if (mv.minHits && mv.maxHits && mv.maxHits > 1) {
      const roll = Math.random();
      hits = mv.minHits === mv.maxHits ? mv.minHits
        : roll < 0.375 ? 2 : roll < 0.75 ? 3 : roll < 0.875 ? 4 : 5;
    }

    await lungeAnim(atkSide, atkSide === scene.me);
    let totalDmg = 0, lastCrit = false;
    for (let h = 0; h < hits && def.hp > 0; h++) {
      let dmg;
      if (FIXED[mv.name]) dmg = FIXED[mv.name]();
      else if (LEVEL_DMG.has(mv.name)) dmg = atk.level;
      else if (mv.name === 'super-fang') dmg = Math.max(1, Math.floor(def.hp / 2));
      else {
        const critChance = (mv.critRate > 0 || atkSide.focused) ? 25 : 6.25;
        lastCrit = chance(critChance);
        const r = calcDamage(atkSide, defSide, mv, lastCrit);
        dmg = r.dmg;
      }
      await hitAnim(defSide, eff);
      await applyDamage(defSide, dmg);
      totalDmg += dmg;
      if (isPhysicalType(mv.type)) defSide.lastPhysDmg = dmg;
    }
    if (hits > 1) await UI.message(`Hit ${hits} time(s)!`);
    if (lastCrit) await UI.message('A critical hit!');
    if (eff > 1) await UI.message("It's super effective!");
    if (eff < 1) await UI.message("It's not very effective…");

    // Secondary effects
    if (def.hp > 0) {
      if (mv.ailment && mv.ailmentChance > 0 && chance(mv.ailmentChance)) await applyAilment(defSide, mv.ailment);
      if (mv.statChanges.length && mv.statChance > 0 && chance(mv.statChance)) {
        const self = mv.statChanges.every(sc => sc.change > 0);
        await applyStatChanges(self ? atkSide : defSide, mv.statChanges, self ? aname : dname);
      }
      if (mv.flinch > 0 && chance(mv.flinch)) defSide.flinched = true;
    }
    if (mv.drain > 0 && totalDmg > 0) {
      atk.hp = Math.min(atk.stats.hp, atk.hp + Math.max(1, Math.floor(totalDmg * mv.drain / 100)));
      await animHp(atkSide, atk.hp);
      await UI.message(`${dname} had its energy\ndrained!`);
    }
    if (mv.drain < 0 && totalDmg > 0) { // recoil
      await applyDamage(atkSide, Math.max(1, Math.floor(totalDmg * -mv.drain / 100)));
      await UI.message(`${aname} is hit with recoil!`);
    }
    if (isStruggle) {
      await applyDamage(atkSide, Math.max(1, Math.floor(atk.stats.hp / 4)));
      await UI.message(`${aname} is hit with recoil!`);
    }
    if (SUICIDE.has(mv.name)) {
      atk.hp = 0; await animHp(atkSide, 0);
    }
    return def.hp <= 0;
  }

  async function endOfTurn(side, other) {
    const mon = side.mon, name = Pkmn.dname(mon);
    if (mon.hp <= 0) return;
    if (mon.status === 'psn') {
      await UI.message(`${name} is hurt by poison!`);
      await applyDamage(side, Math.max(1, Math.floor(mon.stats.hp / 8)));
    } else if (mon.status === 'brn') {
      await UI.message(`${name} is hurt by its burn!`);
      await applyDamage(side, Math.max(1, Math.floor(mon.stats.hp / 8)));
    }
    if (side.seeded && mon.hp > 0 && other.mon.hp > 0) {
      await UI.message(`${name}'s health is sapped\nby LEECH SEED!`);
      const d = Math.max(1, Math.floor(mon.stats.hp / 8));
      await applyDamage(side, d);
      other.mon.hp = Math.min(other.mon.stats.hp, other.mon.hp + d);
      await animHp(other, other.mon.hp);
    }
    if (side.reflect > 0) side.reflect--;
    if (side.lightScreen > 0) side.lightScreen--;
  }

  // Enemy AI: weighted toward best expected damage.
  function pickEnemyMove(foe, me) {
    const usable = moveList(foe).filter(m => m.pp > 0);
    if (!usable.length) return null; // struggle
    if (chance(20)) return usable[rnd(usable.length)];
    let best = usable[0], bestScore = -1;
    for (const slot of usable) {
      const mv = MOVES[slot.name];
      let score;
      if (!mv.power) score = foe.mon.hp === foe.mon.stats.hp ? 25 : 8; // status moves early
      else score = mv.power * typeEffect(mv.type, types(me)) * (types(foe).includes(mv.type) ? 1.5 : 1) / 100 * (mv.accuracy ?? 100);
      if (score > bestScore) { bestScore = score; best = slot; }
    }
    return best;
  }

  // Gen-3 capture formula
  function tryCapture(mon, ballMult) {
    const M = mon.stats.hp, Hcur = mon.hp;
    const rate = Pkmn.species(mon).catchRate;
    const statusBonus = mon.status === 'slp' || mon.status === 'frz' ? 2
      : mon.status ? 1.5 : 1;
    const a = Math.min(255, ((3 * M - 2 * Hcur) * rate * ballMult) / (3 * M) * statusBonus);
    if (a >= 255) return 4;
    const b = Math.floor(1048560 / Math.sqrt(Math.sqrt(16711680 / a)));
    let shakes = 0;
    for (let i = 0; i < 4; i++) {
      if (rnd(65536) < b) shakes++;
      else break;
    }
    return shakes;
  }

  // ---- Exp / level-ups -----------------------------------------------------
  async function giveExp(save, mePlace, defeated, isTrainer) {
    const mon = scene.me.mon;
    if (mon.hp <= 0) return;
    const gained = Pkmn.expGain(defeated, isTrainer);
    await UI.message(`${Pkmn.dname(mon)} gained\n${gained} EXP. points!`);
    const sp = Pkmn.species(mon);
    mon.exp += gained;
    let newLevel = Pkmn.levelForExp(sp.growth, mon.exp);
    while (mon.level < newLevel) {
      mon.level++;
      Pkmn.recalc(mon);
      Audio2.levelUp();
      await UI.message(`${Pkmn.dname(mon)} grew to\nLV ${mon.level}!`);
      for (const mvName of Pkmn.movesLearnedAt(mon, mon.level)) {
        await learnMove(mon, mvName);
      }
      const evoTo = Pkmn.levelEvolution(mon);
      if (evoTo) save.pendingEvos.push({ mon, to: evoTo });
    }
  }

  async function learnMove(mon, mvName) {
    const mv = MOVES[mvName];
    if (mon.moves.length < 4) {
      mon.moves.push({ name: mvName, pp: mv.pp, maxPp: mv.pp });
      Audio2.levelUp();
      await UI.message(`${Pkmn.dname(mon)} learned\n${mv.displayName.toUpperCase()}!`);
      return;
    }
    await UI.message(`${Pkmn.dname(mon)} wants to learn\n${mv.displayName.toUpperCase()}!`);
    const ok = await UI.confirm(`Forget a move to make room\nfor ${mv.displayName.toUpperCase()}?`);
    if (!ok) { await UI.message(`${Pkmn.dname(mon)} did not learn\n${mv.displayName.toUpperCase()}.`); return; }
    const pick = await UI.menu(mon.moves.map(m => MOVES[m.name].displayName.toUpperCase()), { x: 120, y: 40 });
    if (pick < 0) { await UI.message(`${Pkmn.dname(mon)} did not learn\n${mv.displayName.toUpperCase()}.`); return; }
    const old = MOVES[mon.moves[pick].name].displayName.toUpperCase();
    mon.moves[pick] = { name: mvName, pp: mv.pp, maxPp: mv.pp };
    await UI.message(`1, 2 and… Poof!\n${Pkmn.dname(mon)} forgot ${old}\nand learned ${mv.displayName.toUpperCase()}!`);
  }

  // ---- Item use (shared with overworld via Game) ----------------------------
  async function useItemOnMon(save, itemId, mon) {
    const item = Pkmn.ITEMS[itemId];
    if (item.kind === 'heal') {
      if (mon.hp <= 0 || mon.hp >= mon.stats.hp) { await UI.message("It won't have any effect."); return false; }
      mon.hp = Math.min(mon.stats.hp, mon.hp + item.amount);
      Audio2.heal();
      await UI.message(`${Pkmn.dname(mon)}'s HP was restored.`);
    } else if (item.kind === 'status') {
      if (!mon.status) { await UI.message("It won't have any effect."); return false; }
      mon.status = null;
      Audio2.heal();
      await UI.message(`${Pkmn.dname(mon)} became healthy.`);
    } else if (item.kind === 'revive') {
      if (mon.hp > 0) { await UI.message("It won't have any effect."); return false; }
      mon.hp = Math.floor(mon.stats.hp / 2);
      Audio2.heal();
      await UI.message(`${Pkmn.dname(mon)} was revived!`);
    } else {
      return false;
    }
    save.bag[itemId]--;
    return true;
  }

  // ---- Main battle script ----------------------------------------------------
  // opts: { wild: mon } or { trainer: {name, party:[mon...], prize, intro, defeat} }
  // Returns 'win' | 'lose' | 'run' | 'caught'
  async function start(save, opts) {
    Audio2.music('battle');
    const firstAlive = save.party.find(m => m.hp > 0);
    scene = {
      me: makeSide(firstAlive),
      foe: makeSide(opts.wild ?? opts.trainer.party[0]),
      ballAnim: null,
    };
    scene.me.visible = true; scene.foe.visible = true;
    scene.me.ox = scene.me.oy = scene.foe.ox = scene.foe.oy = 0;
    scene.me.flash = scene.foe.flash = 0;
    let foeIndex = 0;
    save.seen[scene.foe.mon.id] = true;

    if (opts.wild) await UI.message(`Wild ${Pkmn.dname(scene.foe.mon)} appeared!`);
    else {
      await UI.message(`${opts.trainer.name} would like\nto battle!`);
      if (opts.trainer.intro) await UI.message(opts.trainer.intro);
      await UI.message(`${opts.trainer.name} sent out\n${Pkmn.dname(scene.foe.mon)}!`);
    }
    await UI.message(`Go! ${Pkmn.dname(scene.me.mon)}!`);

    let runAttempts = 0;
    let result = null;

    while (!result) {
      // --- player chooses ---
      let playerAction = null; // {type:'move',slot} {type:'switch',idx} {type:'item',id} {type:'run'}
      while (!playerAction) {
        const top = await UI.menu(['FIGHT', 'BAG', 'POKéMON', 'RUN'], { x: 150, y: 112, w: 88, cancel: false });
        if (top === 0) {
          const usable = moveList(scene.me);
          if (!usable.some(m => m.pp > 0)) { playerAction = { type: 'struggle' }; break; }
          const labels = usable.map(m => `${MOVES[m.name].displayName.toUpperCase().slice(0, 12)} ${m.pp}/${m.maxPp}`);
          const pick = await UI.menu(labels, { x: 100, y: 112 - usable.length * 14, w: 138 });
          if (pick >= 0) {
            if (usable[pick].pp <= 0) { await UI.message("There's no PP left for\nthis move!"); continue; }
            playerAction = { type: 'move', slot: usable[pick] };
          }
        } else if (top === 1) {
          const itemId = await UI.bag(save.bag, { battle: true });
          if (!itemId) continue;
          const item = Pkmn.ITEMS[itemId];
          if (item.kind === 'ball') {
            if (!opts.wild) { await UI.message("You can't catch a\ntrainer's POKéMON!"); continue; }
            playerAction = { type: 'ball', id: itemId };
          } else if (item.kind === 'stone' || item.kind === 'key') {
            await UI.message("This isn't the time to\nuse that!"); continue;
          } else {
            const idx = await UI.party(save.party, 'select', 'Use on which POKéMON?');
            if (idx < 0) continue;
            if (await useItemOnMon(save, itemId, save.party[idx])) {
              if (save.party[idx] === scene.me.mon) await animHp(scene.me, scene.me.mon.hp);
              playerAction = { type: 'item' };
            }
          }
        } else if (top === 2) {
          const idx = await UI.party(save.party, 'select', 'Switch to which POKéMON?');
          if (idx < 0) continue;
          const pick = save.party[idx];
          if (pick === scene.me.mon) { await UI.message(`${Pkmn.dname(pick)} is already\nin battle!`); continue; }
          if (pick.hp <= 0) { await UI.message(`${Pkmn.dname(pick)} has no\nenergy left to battle!`); continue; }
          playerAction = { type: 'switch', idx };
        } else if (top === 3) {
          if (!opts.wild) { await UI.message("No! There's no running\nfrom a TRAINER battle!"); continue; }
          playerAction = { type: 'run' };
        }
      }

      // --- run attempt resolves before anything ---
      if (playerAction.type === 'run') {
        runAttempts++;
        const f = (effStat(scene.me, 'spe') * 128 / Math.max(1, effStat(scene.foe, 'spe')) + 30 * runAttempts) % 256;
        if (rnd(256) < f) { Audio2.run(); await UI.message('Got away safely!'); result = 'run'; break; }
        await UI.message("Can't escape!");
        const em = pickEnemyMove(scene.foe, scene.me);
        const r = await execMove(scene.foe, scene.me, em, !em);
        if (await handleMyFaint(save, opts)) { result = 'lose'; break; }
        if (r === 'self' && await handleFoeFaint(save, opts, () => foeIndex++)) { result = 'win'; break; }
        await endOfTurn(scene.me, scene.foe); await endOfTurn(scene.foe, scene.me);
        if (await handleMyFaint(save, opts)) { result = 'lose'; break; }
        continue;
      }

      // --- ball throw ---
      if (playerAction.type === 'ball') {
        save.bag[playerAction.id]--;
        const item = Pkmn.ITEMS[playerAction.id];
        await UI.message(`You threw a ${item.name}!`);
        Audio2.thrown();
        scene.ballAnim = { x: 60, y: 80 };
        for (let i = 0; i < 12; i++) {
          scene.ballAnim.x += 9; scene.ballAnim.y = 80 - Math.sin(i / 11 * Math.PI) * 50;
          await wait(30);
        }
        scene.foe.visible = false;
        scene.ballAnim = { x: 172, y: 60 };
        const shakes = tryCapture(scene.foe.mon, item.mult);
        for (let i = 0; i < Math.min(shakes, 3); i++) {
          await wait(500); Audio2.catchClick();
          scene.ballAnim.x = 169; await wait(120); scene.ballAnim.x = 175; await wait(120); scene.ballAnim.x = 172;
        }
        if (shakes === 4) {
          await wait(400);
          Audio2.catchSuccess();
          const caughtMon = scene.foe.mon;
          await UI.message(`Gotcha!\n${Pkmn.dname(caughtMon)} was caught!`);
          save.caught[caughtMon.id] = true; save.seen[caughtMon.id] = true;
          caughtMon.status = null;
          if (save.party.length < 6) {
            save.party.push(caughtMon);
            await UI.message(`${Pkmn.dname(caughtMon)} was added to\nyour party!`);
          } else {
            save.box.push(caughtMon);
            await UI.message(`${Pkmn.dname(caughtMon)} was sent to\nthe PC BOX!`);
          }
          result = 'caught';
          break;
        }
        await wait(400);
        scene.foe.visible = true; scene.ballAnim = null;
        await UI.message(['Oh no! The POKéMON\nbroke free!', 'Aww! It appeared to be\ncaught!', 'Aargh! Almost had it!', 'Shoot! It was so close,\ntoo!'][shakes]);
        const em = pickEnemyMove(scene.foe, scene.me);
        const r = await execMove(scene.foe, scene.me, em, !em);
        if (await handleMyFaint(save, opts)) { result = 'lose'; break; }
        if (r === 'self' && await handleFoeFaint(save, opts, () => foeIndex++)) { result = 'win'; break; }
        await endOfTurn(scene.me, scene.foe); await endOfTurn(scene.foe, scene.me);
        if (await handleMyFaint(save, opts)) { result = 'lose'; break; }
        continue;
      }

      // --- switch / item: enemy attacks free ---
      if (playerAction.type === 'switch' || playerAction.type === 'item' || playerAction.type === 'struggle' && false) {
        if (playerAction.type === 'switch') {
          await UI.message(`${Pkmn.dname(scene.me.mon)}, come back!`);
          scene.me = makeSide(save.party[playerAction.idx]);
          scene.me.visible = true; scene.me.ox = scene.me.oy = scene.me.flash = 0;
          await UI.message(`Go! ${Pkmn.dname(scene.me.mon)}!`);
        }
        const em = pickEnemyMove(scene.foe, scene.me);
        const r = await execMove(scene.foe, scene.me, em, !em);
        if (await handleMyFaint(save, opts)) { result = 'lose'; break; }
        if (r === 'self' && await handleFoeFaint(save, opts, () => foeIndex++)) { result = 'win'; break; }
        await endOfTurn(scene.me, scene.foe); await endOfTurn(scene.foe, scene.me);
        if (await handleMyFaint(save, opts)) { result = 'lose'; break; }
        continue;
      }

      // --- both use moves: order by priority then speed ---
      const myStruggle = playerAction.type === 'struggle';
      const enemySlot = pickEnemyMove(scene.foe, scene.me);
      const myPrio = myStruggle ? 0 : MOVES[playerAction.slot.name].priority;
      const foePrio = enemySlot ? MOVES[enemySlot.name].priority : 0;
      const meFirst = myPrio !== foePrio ? myPrio > foePrio
        : effStat(scene.me, 'spe') === effStat(scene.foe, 'spe') ? Math.random() < 0.5
        : effStat(scene.me, 'spe') > effStat(scene.foe, 'spe');

      const order = meFirst
        ? [[scene.me, scene.foe, playerAction.slot, myStruggle], [scene.foe, scene.me, enemySlot, !enemySlot]]
        : [[scene.foe, scene.me, enemySlot, !enemySlot], [scene.me, scene.foe, playerAction.slot, myStruggle]];

      for (const [a, d, slot, struggle] of order) {
        if (a.mon.hp <= 0) continue;
        const r = await execMove(a, d, slot, struggle);
        if (d === scene.foe && (r === true || scene.foe.mon.hp <= 0)) {
          if (await handleFoeFaint(save, opts, () => foeIndex++)) { result = 'win'; }
          break;
        }
        if (d === scene.me && (r === true || scene.me.mon.hp <= 0)) {
          if (await handleMyFaint(save, opts)) { result = 'lose'; }
          break;
        }
        if (a.mon.hp <= 0) { // suicide / recoil / confusion
          if (a === scene.foe) { if (await handleFoeFaint(save, opts, () => foeIndex++)) result = 'win'; }
          else if (await handleMyFaint(save, opts)) result = 'lose';
          break;
        }
      }
      if (result) break;
      await endOfTurn(scene.me, scene.foe);
      if (scene.me.mon.hp <= 0 && await handleMyFaint(save, opts)) { result = 'lose'; break; }
      await endOfTurn(scene.foe, scene.me);
      if (scene.foe.mon.hp <= 0 && await handleFoeFaint(save, opts, () => foeIndex++)) { result = 'win'; break; }
    }

    // Trainer victory payout
    if (result === 'win' && opts.trainer) {
      if (opts.trainer.defeat) await UI.message(opts.trainer.defeat);
      save.money += opts.trainer.prize;
      await UI.message(`You got $${opts.trainer.prize}\nfor winning!`);
    }
    scene = null;
    return result;

    async function handleFoeFaint(save2, o, advance) {
      if (scene.foe.mon.hp > 0) return false;
      Audio2.faint();
      scene.foe.visible = false;
      await UI.message(`${o.wild ? 'Wild ' : ''}${Pkmn.dname(scene.foe.mon)}\nfainted!`);
      await giveExp(save2, 0, scene.foe.mon, !o.wild);
      if (o.trainer) {
        advance();
        const next = o.trainer.party[++foeIndex - foeIndex + foeIndex] ?? null;
      }
      if (o.trainer && foeIndex + 1 < o.trainer.party.length) {
        foeIndex++;
        scene.foe = makeSide(o.trainer.party[foeIndex]);
        scene.foe.visible = true; scene.foe.ox = scene.foe.oy = scene.foe.flash = 0;
        save2.seen[scene.foe.mon.id] = true;
        await UI.message(`${o.trainer.name} sent out\n${Pkmn.dname(scene.foe.mon)}!`);
        return false;
      }
      return true;
    }

    async function handleMyFaint(save2, o) {
      if (scene.me.mon.hp > 0) return false;
      Audio2.faint();
      scene.me.visible = false;
      await UI.message(`${Pkmn.dname(scene.me.mon)} fainted!`);
      const alive = save2.party.filter(m => m.hp > 0);
      if (!alive.length) return true;
      let idx = -1;
      while (idx < 0 || save2.party[idx].hp <= 0) {
        idx = await UI.party(save2.party, 'select', 'Choose the next POKéMON.');
      }
      scene.me = makeSide(save2.party[idx]);
      scene.me.visible = true; scene.me.ox = scene.me.oy = scene.me.flash = 0;
      await UI.message(`Go! ${Pkmn.dname(scene.me.mon)}!`);
      return false;
    }
  }

  return { start, draw, active: () => !!scene, useItemOnMon, learnMove };
})();
